import { AI_SENT_QUESTION_IDS } from './aiDraft';
import { redactText } from './redact';

type Answer = string | string[];

/** 生成の前に必ず答える質問（validation.ts の REQUIRED_FOR_ANALYSIS と同じ 4 問。設計 §1） */
export const AI_REQUIRED_QUESTION_IDS = ['q-url', 'q-purpose', 'q-issue', 'q-improve'] as const;

/** validation.ts の isAnswered と同じ判定 */
export function isAnsweredValue(v: unknown): boolean {
  return Array.isArray(v) ? v.length > 0 : typeof v === 'string' && v.trim().length > 0;
}

/** 欠けている必須の質問 ID */
export function missingRequired(answers: Record<string, unknown>): string[] {
  return AI_REQUIRED_QUESTION_IDS.filter((id) => !isAnsweredValue(answers[id]));
}

/** buildProposal.ts の hostnameOf と同じ規則（先頭の www. を除く）。解釈できなければ空文字 */
export function hostnameOf(url: string): string {
  try {
    return new URL(url.trim()).hostname.replace(/^www\./, '');
  } catch {
    return '';
  }
}

const asList = (v: unknown): string[] =>
  Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string') : typeof v === 'string' && v.trim() ? [v] : [];

export interface SentAnswers {
  /** 送る回答（質問 ID → 除去済みの値）。q-url はホスト名だけ、q-competitor は含めない（competitorHosts へ） */
  answers: Record<string, Answer>;
  /** 現行サイトの URL（取得に使う。AI へは送らない） */
  siteUrl: string;
  hostname: string;
  competitorHosts: string[];
}

/** 回答から AI へ送るものを作る（設計 §4。送らない質問 q-infra・q-dns-* は AI_SENT_QUESTION_IDS に無い） */
export function buildSentAnswers(raw: Record<string, unknown>): SentAnswers {
  const siteUrl = asList(raw['q-url'])[0]?.trim() ?? '';
  const hostname = hostnameOf(siteUrl);
  const competitorHosts = [...new Set(asList(raw['q-competitor']).map(hostnameOf).filter((h) => h.length > 0))];
  const answers: Record<string, Answer> = {};
  for (const id of AI_SENT_QUESTION_IDS) {
    if (id === 'q-competitor') continue;
    if (id === 'q-url') {
      if (hostname) answers[id] = hostname;
      continue;
    }
    const v = raw[id];
    if (!isAnsweredValue(v)) continue;
    answers[id] = Array.isArray(v) ? asList(v).map((x) => redactText(x.trim())) : redactText(String(v).trim());
  }
  return { answers, siteUrl, hostname, competitorHosts };
}

/** キーを並べた JSON（同じ内容なら同じ文字列） */
export function canonicalJson(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonicalJson).join(',')}]`;
  if (v && typeof v === 'object') {
    const o = v as Record<string, unknown>;
    return `{${Object.keys(o).sort().filter((k) => o[k] !== undefined).map((k) => `${JSON.stringify(k)}:${canonicalJson(o[k])}`).join(',')}}`;
  }
  return JSON.stringify(v ?? null);
}

// ---------------- SHA-256（FIPS 180-4） ----------------
const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01,
  0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
  0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147,
  0x06ca6351, 0x14292967, 0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08,
  0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

/** UTF-8 の SHA-256（16 進 64 文字） */
export function sha256Hex(text: string): string {
  const bytes = new TextEncoder().encode(text);
  const bitLen = bytes.length * 8;
  const total = (((bytes.length + 9 + 63) >> 6) << 6);
  const m = new Uint8Array(total);
  m.set(bytes);
  m[bytes.length] = 0x80;
  const view = new DataView(m.buffer);
  view.setUint32(total - 8, Math.floor(bitLen / 0x100000000));
  view.setUint32(total - 4, bitLen >>> 0);
  const h = new Uint32Array([0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]);
  const w = new Uint32Array(64);
  const rotr = (x: number, n: number) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < total; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = view.getUint32(off + i * 4);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, hh] = h;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (hh + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      hh = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    h[0] = (h[0] + a) >>> 0; h[1] = (h[1] + b) >>> 0; h[2] = (h[2] + c) >>> 0; h[3] = (h[3] + d) >>> 0;
    h[4] = (h[4] + e) >>> 0; h[5] = (h[5] + f) >>> 0; h[6] = (h[6] + g) >>> 0; h[7] = (h[7] + hh) >>> 0;
  }
  return Array.from(h, (x) => x.toString(16).padStart(8, '0')).join('');
}

/** 送る回答のハッシュ（aiDrafts.answersHash）。回答そのものではなく送る形（除去済み）から作る */
export function answersHash(raw: Record<string, unknown>): string {
  const s = buildSentAnswers(raw);
  return `sha256:${sha256Hex(canonicalJson({ answers: s.answers, competitorHosts: s.competitorHosts, siteUrl: s.siteUrl }))}`;
}

/** AI の設定のハッシュ（aiDrafts.configHash。モデル・promptVersion・effort） */
export function configHash(config: { model: string; promptVersion: string; effort: string }): string {
  return `sha256:${sha256Hex(canonicalJson({ model: config.model, promptVersion: config.promptVersion, effort: config.effort }))}`;
}
